#include <vector>
#include <string>
#include <cstddef>
#include <omp.h>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    // Return books.size() if no matching book is found.
    size_t lastIndex = books.size();

    #pragma omp parallel
    {
        size_t localLast = books.size();

        #pragma omp for nowait
        for (std::size_t i = 0; i < books.size(); ++i) {
            if (books[i].pages < 100) {
                if (localLast == books.size() || i > localLast) {
                    localLast = i;
                }
            }
        }

        #pragma omp critical
        {
            if (localLast != books.size() &&
                (lastIndex == books.size() || localLast > lastIndex)) {
                lastIndex = localLast;
            }
        }
    }

    return lastIndex;
}
